sql.where:
u.role_type = 1

    and u.user_id = #{query.userId}


    and u.stage = #{query.stage}


    and u.grade = #{query.grade}


    and u.status = #{query.status}


    and (u.username like concat('%', #{query.usernameFuzzy}, '%')
        or u.nick_name like concat('%', #{query.usernameFuzzy}, '%')
        or u.email like concat('%', #{query.usernameFuzzy}, '%'))


    and u.email like concat('%', #{query.emailFuzzy}, '%')


    and (u.nick_name like concat('%', #{query.nickNameFuzzy}, '%')
        or u.username like concat('%', #{query.nickNameFuzzy}, '%'))

mapper.select:
SELECT u.user_id, u.username, u.email, u.nick_name, u.stage, u.grade, u.status, u.last_login_time, (SELECT COUNT(*) FROM course_study_progress c WHERE c.user_id = u.user_id) AS course_course_count, (SELECT COUNT(*) FROM course_study_progress c WHERE c.user_id = u.user_id AND c.progress >= 100) AS course_finished_count, (SELECT COALESCE(ROUND(AVG(c.progress)), 0) FROM course_study_progress c WHERE c.user_id = u.user_id) AS course_avg_progress, (SELECT COUNT(*) FROM practice_record p WHERE p.user_id = u.user_id) AS practice_count, (SELECT COALESCE(SUM(p.is_correct), 0) FROM practice_record p WHERE p.user_id = u.user_id) AS practice_correct_count, (SELECT COALESCE(ROUND(SUM(p.is_correct) * 100.0 / NULLIF(COUNT(*), 0), 1), 0) FROM practice_record p WHERE p.user_id = u.user_id) AS practice_accuracy, (SELECT COUNT(*) FROM resource_info r WHERE r.owner_id = u.user_id) AS wiki_resource_count, (SELECT COALESCE(SUM(r.file_size), 0) FROM resource_info r WHERE r.owner_id = u.user_id) AS wiki_resource_bytes, (SELECT COUNT(*) FROM agent_session s WHERE s.user_id = u.user_id) AS ai_session_count, (SELECT COUNT(*) FROM agent_message m WHERE m.user_id = u.user_id) AS ai_message_count, (SELECT COALESCE(SUM(m.prompt_tokens + m.completion_tokens), 0) FROM agent_message m WHERE m.user_id = u.user_id) AS ai_token_count, (SELECT COALESCE(ROUND(AVG(k.mastery_score)), 0) FROM knowledge_mastery k WHERE k.user_id = u.user_id) AS mastery_avg_score, (SELECT COUNT(*) FROM knowledge_mastery k WHERE k.user_id = u.user_id AND k.status = 2) AS mastery_mastered_count FROM user_info u
order by ${query.orderBy}
limit #{query.simplePage.start}, #{query.simplePage.end}
